SELECT id, category, stock_qty, launch_date, ROW_NUMBER() OVER (PARTITION BY brand ORDER BY cost DESC, id) AS row_seq, FIRST_VALUE(cost, TRUE) OVER (PARTITION BY brand ORDER BY launch_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_cost, SUM(stock_qty) OVER (PARTITION BY MONTH(launch_date), brand ORDER BY price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_stock_qty, ROW_NUMBER() OVER (PARTITION BY category ORDER BY launch_date, id) AS seq_no FROM products
